use std::io::{self, BufRead, Write};
use std::collections::HashMap;

mod diff_parser;
mod color_parser;
mod renderer;

use diff_parser::{DiffLine, DiffHunk, parse_diff_line};
use color_parser::{ColorSpec, parse_color_specs};
use renderer::Renderer;

#[derive(Debug)]
struct Args {
    color_specs: Vec<ColorSpec>,
    line_numbers: Option<String>,
}

fn parse_args() -> Args {
    let args: Vec<String> = std::env::args().collect();
    let mut color_specs = Vec::new();
    let mut line_numbers = None;
    let mut i = 1;

    while i < args.len() {
        match args[i].as_str() {
            "--version" | "-V" => {
                println!("diffr 0.1.5");
                std::process::exit(0);
            }
            "--help" | "-h" => {
                print_help();
                std::process::exit(0);
            }
            "--colors" => {
                i += 1;
                if i < args.len() {
                    match parse_color_specs(&args[i]) {
                        Ok(spec) => color_specs.push(spec),
                        Err(e) => {
                            eprintln!("bad argument: '{}'", args[i]);
                            print_short_help();
                            std::process::exit(2);
                        }
                    }
                }
            }
            "--line-numbers" => {
                if i + 1 < args.len() && !args[i + 1].starts_with("--") {
                    i += 1;
                    line_numbers = Some(args[i].clone());
                } else {
                    line_numbers = Some("compact".to_string());
                }
            }
            _ => {
                eprintln!("Unknown argument: {}", args[i]);
                std::process::exit(2);
            }
        }
        i += 1;
    }

    Args {
        color_specs,
        line_numbers,
    }
}

fn print_help() {
    println!("diffr 0.1.5");
    println!("Nathan Moreau <nathan.moreau@m4x.org>");
    println!();
    println!("diffr adds word-level diff on top of unified diffs.");
    println!("word-level diff information is displayed using text attributes.");
    println!();
    println!("USAGE:");
    println!("    diffr reads from standard input and writes to standard output.");
    println!();
    println!("    Typical usage is for interactive use of diff:");
    println!("    diff -u <file1> <file2> | diffr");
    println!("    git show | diffr");
    println!();
    println!("OPTIONS:");
    println!("        --colors <COLOR_SPEC>...");
    println!("            Configure color settings for console ouput.");
    println!();
    println!("            There are four faces to customize:");
    println!("            +----------------+--------------+----------------+");
    println!("            |  line prefix   |      +       |       -        |");
    println!("            +----------------+--------------+----------------+");
    println!("            | common segment |    added     |    removed     |");
    println!("            | unique segment | refine-added | refine-removed |");
    println!("            +----------------+--------------+----------------+");
    println!();
    println!("            The customization allows");
    println!("            - to change the foreground or background color;");
    println!("            - to set or unset the attributes 'bold', 'intense', 'underline';");
    println!("            - to clear all attributes.");
    println!();
    println!("            Customization is done passing a color_spec argument.");
    println!("            This flag may be provided multiple times.");
    println!();
    println!("            The syntax is the following:");
    println!();
    println!("            color_spec = face-name + ':' + attributes");
    println!("            attributes = attribute");
    println!("                       | attribute + ':' + attributes");
    println!("            attribute  = ('foreground' | 'background') + ':' + color");
    println!("                       | (<empty> | 'no') + font-flag");
    println!("                       | 'none'");
    println!("            font-flag  = 'italic'");
    println!("                       | 'bold'");
    println!("                       | 'intense'");
    println!("                       | 'underline'");
    println!("            color      = 'none'");
    println!("                       | [0-255]");
    println!("                       | [0-255] + ',' + [0-255] + ',' + [0-255]");
    println!("                       | ('black', 'blue', 'green', 'red',");
    println!("                          'cyan', 'magenta', 'yellow', 'white')");
    println!();
    println!("            For example, the color_spec");
    println!();
    println!("                'refine-added:background:blue:bold'");
    println!();
    println!("            sets the color of unique added segments with");
    println!("            a blue background, written with a bold font.");
    println!();
    println!("        --line-numbers <compact|aligned>");
    println!("            Display line numbers. Style is optional.");
    println!("            When style = 'compact', take as little width as possible.");
    println!("            When style = 'aligned', align to tab stops (useful if tab is used for indentation). [default: compact]");
    println!();
    println!("    -h, --help");
    println!("            Prints help information");
    println!();
    println!("    -V, --version");
    println!("            Prints version information");
}

fn print_short_help() {
    println!("diffr 0.1.5");
    println!("Nathan Moreau <nathan.moreau@m4x.org>");
    println!();
    println!("diffr adds word-level diff on top of unified diffs.");
    println!("word-level diff information is displayed using text attributes.");
    println!();
    println!("USAGE:");
    println!("    diffr reads from standard input and writes to standard output.");
    println!();
    println!("    Typical usage is for interactive use of diff:");
    println!("    diff -u <file1> <file2> | diffr");
    println!("    git show | diffr");
    println!();
    println!("OPTIONS:");
    println!("        --colors <COLOR_SPEC>...    Configure color settings.");
    println!("        --line-numbers              Display line numbers.");
    println!("    -h, --help                      Prints help information");
    println!("    -V, --version                   Prints version information");
}

fn main() {
    let args = parse_args();
    let mut renderer = Renderer::new(args.color_specs, args.line_numbers);

    let stdin = io::stdin();
    let reader = stdin.lock();
    let mut stdout = io::stdout();

    let mut hunks = Vec::new();
    let mut current_hunk: Option<DiffHunk> = None;
    let mut in_diff = false;

    for line in reader.lines() {
        if let Ok(line) = line {
            let diff_line = parse_diff_line(&line);

            match diff_line {
                DiffLine::DiffHeader => {
                    in_diff = true;
                    let output = renderer.render_line(&line);
                    let _ = stdout.write_all(output.as_bytes());
                }
                DiffLine::HunkHeader => {
                    if let Some(hunk) = current_hunk.take() {
                        hunks.push(hunk);
                    }
                    current_hunk = Some(DiffHunk {
                        header: line.clone(),
                        lines: Vec::new(),
                    });
                    let output = renderer.render_line(&line);
                    let _ = stdout.write_all(output.as_bytes());
                }
                DiffLine::RemovedLine | DiffLine::AddedLine | DiffLine::ContextLine => {
                    if let Some(ref mut hunk) = current_hunk {
                        hunk.lines.push((diff_line, line.clone()));
                    }
                }
                DiffLine::Other => {
                    if let Some(ref mut hunk) = current_hunk {
                        hunk.lines.push((diff_line, line.clone()));
                    } else {
                        let output = renderer.render_line(&line);
                        let _ = stdout.write_all(output.as_bytes());
                    }
                }
            }
        }
    }

    if let Some(hunk) = current_hunk.take() {
        hunks.push(hunk);
    }

    // Now process the hunks
    for hunk in hunks {
        process_hunk(&hunk, &mut renderer, &mut stdout);
    }
}

fn process_hunk(hunk: &DiffHunk, renderer: &mut Renderer, stdout: &mut std::io::Stdout) {
    // Group paired removed/added lines
    let mut i = 0;
    let lines = &hunk.lines;

    while i < lines.len() {
        let (line_type, line_text) = &lines[i];

        match line_type {
            diff_parser::DiffLine::RemovedLine => {
                // Find the next added line
                if i + 1 < lines.len() {
                    if let (diff_parser::DiffLine::AddedLine, added_text) = &lines[i + 1] {
                        // Pair them for word-level diff
                        let rendered = renderer.render_diff_pair(line_text, added_text);
                        let _ = stdout.write_all(rendered.as_bytes());
                        i += 2;
                        continue;
                    }
                }
                // No paired added line
                let output = renderer.render_line(line_text);
                let _ = stdout.write_all(output.as_bytes());
                i += 1;
            }
            diff_parser::DiffLine::AddedLine => {
                // Unpaired added line
                let output = renderer.render_line(line_text);
                let _ = stdout.write_all(output.as_bytes());
                i += 1;
            }
            _ => {
                let output = renderer.render_line(line_text);
                let _ = stdout.write_all(output.as_bytes());
                i += 1;
            }
        }
    }
}
