#[derive(Debug, Clone)]
pub enum Color {
    None,
    Named(String),  // "red", "green", etc.
    Indexed(u8),    // 0-255
    RGB(u8, u8, u8),
}

#[derive(Debug, Clone)]
pub struct ColorSpec {
    pub face: String,
    pub foreground: Option<Color>,
    pub background: Option<Color>,
    pub bold: Option<bool>,
    pub italic: Option<bool>,
    pub underline: Option<bool>,
    pub intense: Option<bool>,
    pub none: bool,
}

impl Default for ColorSpec {
    fn default() -> Self {
        ColorSpec {
            face: String::new(),
            foreground: None,
            background: None,
            bold: None,
            italic: None,
            underline: None,
            intense: None,
            none: false,
        }
    }
}

pub fn parse_color_specs(spec_str: &str) -> Result<ColorSpec, String> {
    let mut spec = ColorSpec::default();
    let parts: Vec<&str> = spec_str.split(':').collect();

    if parts.is_empty() {
        return Err("Empty color spec".to_string());
    }

    spec.face = parts[0].to_string();

    for i in 1..parts.len() {
        let part = parts[i];

        if part == "none" {
            spec.none = true;
        } else if part == "bold" {
            spec.bold = Some(true);
        } else if part == "nobold" {
            spec.bold = Some(false);
        } else if part == "italic" {
            spec.italic = Some(true);
        } else if part == "noitalic" {
            spec.italic = Some(false);
        } else if part == "underline" {
            spec.underline = Some(true);
        } else if part == "noundeline" {
            spec.underline = Some(false);
        } else if part == "intense" {
            spec.intense = Some(true);
        } else if part == "nointense" {
            spec.intense = Some(false);
        } else if part == "foreground" {
            if i + 1 < parts.len() {
                spec.foreground = Some(parse_color(parts[i + 1])?);
                i += 1;
            }
        } else if part == "background" {
            if i + 1 < parts.len() {
                spec.background = Some(parse_color(parts[i + 1])?);
                i += 1;
            }
        }
    }

    Ok(spec)
}

fn parse_color(color_str: &str) -> Result<Color, String> {
    if color_str == "none" {
        return Ok(Color::None);
    }

    // Try named colors
    match color_str {
        "black" | "blue" | "green" | "red" | "cyan" | "magenta" | "yellow" | "white" => {
            return Ok(Color::Named(color_str.to_string()));
        }
        _ => {}
    }

    // Try indexed color (0-255)
    if let Ok(idx) = color_str.parse::<u8>() {
        return Ok(Color::Indexed(idx));
    }

    // Try RGB color (r,g,b)
    let rgb_parts: Vec<&str> = color_str.split(',').collect();
    if rgb_parts.len() == 3 {
        let r = rgb_parts[0].parse::<u8>().map_err(|_| "Invalid RGB")?;
        let g = rgb_parts[1].parse::<u8>().map_err(|_| "Invalid RGB")?;
        let b = rgb_parts[2].parse::<u8>().map_err(|_| "Invalid RGB")?;
        return Ok(Color::RGB(r, g, b));
    }

    Err(format!("Invalid color: {}", color_str))
}

impl Color {
    pub fn to_ansi_foreground(&self) -> String {
        match self {
            Color::None => String::new(),
            Color::Named(name) => {
                match name.as_str() {
                    "black" => "\x1b[30m".to_string(),
                    "red" => "\x1b[31m".to_string(),
                    "green" => "\x1b[32m".to_string(),
                    "yellow" => "\x1b[33m".to_string(),
                    "blue" => "\x1b[34m".to_string(),
                    "magenta" => "\x1b[35m".to_string(),
                    "cyan" => "\x1b[36m".to_string(),
                    "white" => "\x1b[37m".to_string(),
                    _ => String::new(),
                }
            }
            Color::Indexed(idx) => format!("\x1b[38;5;{}m", idx),
            Color::RGB(r, g, b) => format!("\x1b[38;2;{};{};{}m", r, g, b),
        }
    }

    pub fn to_ansi_background(&self) -> String {
        match self {
            Color::None => String::new(),
            Color::Named(name) => {
                match name.as_str() {
                    "black" => "\x1b[40m".to_string(),
                    "red" => "\x1b[41m".to_string(),
                    "green" => "\x1b[42m".to_string(),
                    "yellow" => "\x1b[43m".to_string(),
                    "blue" => "\x1b[44m".to_string(),
                    "magenta" => "\x1b[45m".to_string(),
                    "cyan" => "\x1b[46m".to_string(),
                    "white" => "\x1b[47m".to_string(),
                    _ => String::new(),
                }
            }
            Color::Indexed(idx) => {
                // Bright color indices: 0-7 normal, 8-15 bright
                if *idx <= 7 {
                    let bg = 40 + idx;
                    format!("\x1b[{}m", bg)
                } else {
                    format!("\x1b[48;5;{}m", idx)
                }
            }
            Color::RGB(r, g, b) => format!("\x1b[48;2;{};{};{}m", r, g, b),
        }
    }
}
