use color_parser::parse_color_specs;
use renderer::Renderer;

#[derive(Debug)]
struct Args {
    color_specs: Vec<color_parser::ColorSpec>,
    line_numbers: Option<String>,
}

fn parse_args() -> Args {
    let args: Vec<String> = std::env::args().collect();
    let mut color_specs = Vec::new();
    let mut line_numbers = None;
    let mut i = 1;

    while i < args.len() {
        match args[i].as_str() {
            "--version" | "-V" => {
                println!("diffr 0.1.5");
                std::process::exit(0);
            }
            "--help" | "-h" => {
                print_help();
                std::process::exit(0);
            }
            "--colors" => {
                i += 1;
                if i < args.len() {
                    match parse_color_specs(&args[i]) {
                        Ok(spec) => color_specs.push(spec),
                        Err(_) => {
                            eprintln!("bad argument: '{}'", args[i]);
                            print_short_help();
                            std::process::exit(2);
                        }
                    }
                }
            }
            "--line-numbers" => {
                if i + 1 < args.len() && !args[i + 1].starts_with("--") {
                    i += 1;
                    line_numbers = Some(args[i].clone());
                } else {
                    line_numbers = Some("compact".to_string());
                }
            }
            _ => {
                eprintln!("Unknown argument: {}", args[i]);
                std::process::exit(2);
            }
