use crate::color_parser::{Color, ColorSpec};
use std::collections::HashMap;

pub struct Renderer {
    color_specs: HashMap<String, ColorSpec>,
    _line_numbers_mode: Option<String>,
}

impl Renderer {
    pub fn new(specs: Vec<ColorSpec>, line_numbers_mode: Option<String>) -> Self {
        let mut color_specs = HashMap::new();

        // Initialize default color specs
        color_specs.insert("added".to_string(), ColorSpec {
            face: "added".to_string(),
            foreground: Some(Color::Named("green".to_string())),
            background: None,
            bold: None,
            italic: None,
            underline: None,
            intense: None,
            none: false,
        });

        color_specs.insert("removed".to_string(), ColorSpec {
            face: "removed".to_string(),
            foreground: Some(Color::Named("red".to_string())),
            background: None,
            bold: None,
            italic: None,
            underline: None,
            intense: None,
            none: false,
        });

        color_specs.insert("refine-added".to_string(), ColorSpec {
            face: "refine-added".to_string(),
            foreground: Some(Color::RGB(255, 255, 255)),
            background: Some(Color::Named("green".to_string())),
            bold: Some(true),
            italic: None,
            underline: None,
            intense: None,
            none: false,
        });

        color_specs.insert("refine-removed".to_string(), ColorSpec {
            face: "refine-removed".to_string(),
            foreground: Some(Color::RGB(255, 255, 255)),
            background: Some(Color::Named("red".to_string())),
            bold: Some(true),
            italic: None,
            underline: None,
            intense: None,
            none: false,
        });

        // Override with provided specs
        for spec in specs {
            color_specs.insert(spec.face.clone(), spec);
        }

        Renderer {
            color_specs,
            _line_numbers_mode: line_numbers_mode,
        }
    }

    pub fn render_line(&self, line: &str) -> String {
        let reset = "\x1b[0m";
        format!("{}{}{}\n", reset, line, reset)
    }

    pub fn render_diff_pair(&self, removed_line: &str, added_line: &str) -> String {
        let mut result = String::new();

        // Extract the actual content (skip the first character which is the prefix)
        let removed_content = if removed_line.len() > 1 {
            &removed_line[1..]
        } else {
            ""
        };

        let added_content = if added_line.len() > 1 {
            &added_line[1..]
        } else {
            ""
        };

        // Find differences
        let diff_removed = find_diff_regions(removed_content, added_content, true);
        let diff_added = find_diff_regions(removed_content, added_content, false);

        // Render removed line
        let removed_prefix = format!("{}-{}", "\x1b[0m", "\x1b[31m");
        let removed_rendered = apply_diff_highlighting(removed_content, &diff_removed, "removed", "refine-removed", &self.color_specs);
        result.push_str(&format!("{}{}{}\n", removed_prefix, removed_rendered, "\x1b[0m"));

        // Render added line
        let added_prefix = format!("{}{}", "\x1b[0m", "\x1b[32m+");
        let added_rendered = apply_diff_highlighting(added_content, &diff_added, "added", "refine-added", &self.color_specs);
        result.push_str(&format!("{}{}{}\n", added_prefix, added_rendered, "\x1b[0m"));

        result
    }
}

fn find_diff_regions(text1: &str, text2: &str, is_removed: bool) -> Vec<(usize, usize)> {
    let words1 = tokenize(text1);
    let words2 = tokenize(text2);

    let matching = find_matching_words(&words1, &words2);

    if is_removed {
        find_different_spans(&words1, &matching)
    } else {
        find_different_spans(&words2, &matching)
    }
}

fn tokenize(text: &str) -> Vec<(usize, usize, String)> {
    let mut words = Vec::new();
    let mut current_word = String::new();
    let mut start_idx = 0;
    let mut in_word = false;

    for (i, ch) in text.chars().enumerate() {
        if ch.is_whitespace() {
            if in_word {
                words.push((start_idx, i, current_word.clone()));
                current_word.clear();
                in_word = false;
            }
        } else {
            if !in_word {
                start_idx = i;
                in_word = true;
            }
            current_word.push(ch);
        }
    }

    if in_word {
        words.push((start_idx, text.len(), current_word));
    }

    words
}

fn find_matching_words(words1: &[(usize, usize, String)], words2: &[(usize, usize, String)]) -> Vec<bool> {
    let mut matching = vec![false; words1.len()];

    for i in 0..words1.len() {
        for j in 0..words2.len() {
            if words1[i].2 == words2[j].2 {
                matching[i] = true;
                break;
            }
        }
    }

    matching
}

fn find_different_spans(words: &[(usize, usize, String)], matching: &[bool]) -> Vec<(usize, usize)> {
    let mut spans = Vec::new();
    let mut in_diff = false;
    let mut diff_start = 0;

    for i in 0..words.len() {
        if !matching[i] {
            if !in_diff {
                diff_start = words[i].0;
                in_diff = true;
            }
        } else {
            if in_diff {
                spans.push((diff_start, words[i].0));
                in_diff = false;
            }
        }
    }

    if in_diff && !words.is_empty() {
        spans.push((diff_start, words[words.len() - 1].1));
    }

    spans
}

fn apply_diff_highlighting(
    text: &str,
    diff_regions: &[(usize, usize)],
    normal_face: &str,
    refined_face: &str,
    color_specs: &HashMap<String, ColorSpec>,
) -> String {
    let mut result = String::new();
    let reset = "\x1b[0m";

    let normal_spec = color_specs.get(normal_face);
    let refined_spec = color_specs.get(refined_face);

    let mut current_pos = 0;

    for (diff_start, diff_end) in diff_regions {
        // Add normal text before this region
        if current_pos < *diff_start {
            let normal_text = &text[current_pos..*diff_start];
            if let Some(spec) = normal_spec {
                result.push_str(&format_spec_start(spec));
                result.push_str(normal_text);
                result.push_str(reset);
            } else {
                result.push_str(normal_text);
            }
        }

        // Add refined text
        let refined_text = &text[*diff_start..*diff_end];
        if let Some(spec) = refined_spec {
            result.push_str(&format_spec_start(spec));
            result.push_str(refined_text);
            result.push_str(reset);
        } else {
            result.push_str(refined_text);
        }

        current_pos = *diff_end;
    }

    // Add remaining normal text
    if current_pos < text.len() {
        let normal_text = &text[current_pos..];
        if let Some(spec) = normal_spec {
            result.push_str(&format_spec_start(spec));
            result.push_str(normal_text);
            result.push_str(reset);
        } else {
            result.push_str(normal_text);
        }
    }

    result
}

fn format_spec_start(spec: &ColorSpec) -> String {
    let mut result = String::new();

    if spec.none {
        return result;
    }

    // Add bold if not explicitly disabled
    if spec.bold != Some(false) && spec.bold == Some(true) {
        result.push_str("\x1b[1m");
    }

    // Add italic if enabled
    if spec.italic == Some(true) {
        result.push_str("\x1b[3m");
    }

    // Add underline if enabled
    if spec.underline == Some(true) {
        result.push_str("\x1b[4m");
    }

    // Add foreground color
    if let Some(ref color) = spec.foreground {
        result.push_str(&color.to_ansi_foreground());
    }

    // Add background color with possible intense modification
    if let Some(ref color) = spec.background {
        let bg = match color {
            Color::Named(name) if spec.intense == Some(true) => {
                // Bright version of the color
                match name.as_str() {
                    "red" => "\x1b[48;5;9m".to_string(),      // Bright red
                    "green" => "\x1b[48;5;10m".to_string(),    // Bright green
                    "yellow" => "\x1b[48;5;11m".to_string(),   // Bright yellow
                    "blue" => "\x1b[48;5;12m".to_string(),     // Bright blue
                    "magenta" => "\x1b[48;5;13m".to_string(),  // Bright magenta
                    "cyan" => "\x1b[48;5;14m".to_string(),     // Bright cyan
                    "white" => "\x1b[48;5;15m".to_string(),    // Bright white
                    _ => color.to_ansi_background(),
                }
            }
            _ => color.to_ansi_background(),
        };
        result.push_str(&bg);
    }

    result
}
