                let prev_word_end = words[i - 1].1;
                spans.push((diff_start, prev_word_end));
                in_diff = false;
            }
        }
    }

    if in_diff && !words.is_empty() {
        // Include up to the end of the last different word
        spans.push((diff_start, words[words.len() - 1].1));
    }

    spans
}
