                current_word.clear();
                in_word = false;
            }
        } else {
            if !in_word {
                start_idx = i;
                in_word = true;
            }
            current_word.push(ch);
        }
    }

    if in_word {
        words.push((start_idx, text.len(), current_word));
    }

    words
}

fn find_matching_words(words1: &[(usize, usize, String)], words2: &[(usize, usize, String)]) -> Vec<bool> {
    let mut matching = vec![false; words1.len()];

    for i in 0..words1.len() {
        for j in 0..words2.len() {
            if words1[i].2 == words2[j].2 {
                matching[i] = true;
                break;
            }
        }
    }

    matching
}

fn find_different_spans(words: &[(usize, usize, String)], matching: &[bool]) -> Vec<(usize, usize)> {
    let mut spans = Vec::new();
    let mut in_diff = false;
    let mut diff_start = 0;

    for i in 0..words.len() {
        if !matching[i] {
            if !in_diff {
                diff_start = words[i].0;
                in_diff = true;
            }
        } else {
            if in_diff {
