fn print_short_help() {
    println!("diffr 0.1.5");
    println!("Nathan Moreau <nathan.moreau@m4x.org>");
    println!();
    println!("diffr adds word-level diff on top of unified diffs.");
    println!("word-level diff information is displayed using text attributes.");
    println!();
    println!("USAGE:");
    println!("    diffr reads from standard input and writes to standard output.");
    println!();
    println!("    Typical usage is for interactive use of diff:");
    println!("    diff -u <file1> <file2> | diffr");
    println!("    git show | diffr");
    println!();
    println!("OPTIONS:");
    println!("        --colors <COLOR_SPEC>...    Configure color settings.");
    println!("        --line-numbers              Display line numbers.");
    println!("    -h, --help                      Prints help information");
    println!("    -V, --version                   Prints version information");
}

fn main() {
    let args = parse_args();
    let mut renderer = Renderer::new(args.color_specs, args.line_numbers);

    let stdin = io::stdin();
    let reader = stdin.lock();
    let mut stdout = io::stdout();

    let mut hunks = Vec::new();
    let mut current_hunk: Option<DiffHunk> = None;

    for line in reader.lines() {
        if let Ok(line) = line {
            let diff_line = parse_diff_line(&line);

            match diff_line {
                DiffLine::DiffHeader => {
                    let output = renderer.render_line(&line);
                    let _ = stdout.write_all(output.as_bytes());
                }
                DiffLine::HunkHeader => {
                    if let Some(hunk) = current_hunk.take() {
                        hunks.push(hunk);
                    }
                    let (old_start, old_count, new_start, new_count) = parse_hunk_header(&line);
                    current_hunk = Some(DiffHunk {
                        header: line.clone(),
                        lines: Vec::new(),
                        old_start,
                        old_count,
                        new_start,
                        new_count,
                    });
                    let output = renderer.render_line(&line);
                    let _ = stdout.write_all(output.as_bytes());
                }
                DiffLine::RemovedLine | DiffLine::AddedLine | DiffLine::ContextLine => {
                    if let Some(ref mut hunk) = current_hunk {
                        hunk.lines.push((diff_line, line.clone()));
                    }
                }
                DiffLine::Other => {
                    if let Some(ref mut hunk) = current_hunk {
                        hunk.lines.push((diff_line, line.clone()));
                    } else {
                        let output = renderer.render_line(&line);
                        let _ = stdout.write_all(output.as_bytes());
                    }
                }
            }
        }
    }

    if let Some(hunk) = current_hunk.take() {
        hunks.push(hunk);
    }

    // Now process the hunks
    for hunk in hunks {
        process_hunk(&hunk, &mut renderer, &mut stdout);
    }
}

fn process_hunk(hunk: &DiffHunk, renderer: &mut Renderer, stdout: &mut std::io::Stdout) {
    // Set line numbers from hunk header
    renderer.set_line_numbers(hunk.old_start, hunk.new_start);

    // Group paired removed/added lines
    let mut i = 0;
    let lines = &hunk.lines;

    while i < lines.len() {
        let (line_type, line_text) = &lines[i];

        match line_type {
            diff_parser::DiffLine::RemovedLine => {
                // Find the next added line
                if i + 1 < lines.len() {
                    if let (diff_parser::DiffLine::AddedLine, added_text) = &lines[i + 1] {
                        // Pair them for word-level diff
                        let rendered = renderer.render_diff_pair(line_text, added_text);
                        let _ = stdout.write_all(rendered.as_bytes());
                        i += 2;
                        continue;
                    }
                }
                // No paired added line
                let output = renderer.render_line(line_text);
                let _ = stdout.write_all(output.as_bytes());
                i += 1;
            }
            diff_parser::DiffLine::AddedLine => {
                // Unpaired added line
                let output = renderer.render_line(line_text);
                let _ = stdout.write_all(output.as_bytes());
                i += 1;
            }
            diff_parser::DiffLine::ContextLine => {
                let output = renderer.render_context_line(line_text);
                let _ = stdout.write_all(output.as_bytes());
                i += 1;
            }
            _ => {
                let output = renderer.render_line(line_text);
                let _ = stdout.write_all(output.as_bytes());
                i += 1;
            }
        }
    }
}
