#[derive(Debug, Clone, PartialEq)]
pub enum DiffLine {
    DiffHeader,      // --- or +++
    HunkHeader,      // @@
    RemovedLine,     // - at start
    AddedLine,       // + at start
    ContextLine,     // space at start
    Other,
}

pub struct DiffHunk {
    #[allow(dead_code)]
    pub header: String,
    pub lines: Vec<(DiffLine, String)>,
    pub old_start: usize,
    pub old_count: usize,
    pub new_start: usize,
    pub new_count: usize,
}

pub fn parse_diff_line(line: &str) -> DiffLine {
    if line.starts_with("--- ") || line.starts_with("+++ ") {
        DiffLine::DiffHeader
    } else if line.starts_with("@@ ") {
        DiffLine::HunkHeader
    } else if line.starts_with('-') && !line.starts_with("--- ") {
        DiffLine::RemovedLine
    } else if line.starts_with('+') && !line.starts_with("+++ ") {
        DiffLine::AddedLine
    } else if line.starts_with(' ') {
        DiffLine::ContextLine
    } else {
        DiffLine::Other
    }
}

pub fn parse_hunk_header(header: &str) -> (usize, usize, usize, usize) {
    // Format: @@ -old_start,old_count +new_start,new_count @@
    // Example: @@ -1,5 +1,6 @@
    let trimmed = header.trim_start_matches("@@ -").trim_end_matches(" @@");
    let parts: Vec<&str> = trimmed.split(" +").collect();

    let (old_start, old_count) = if let Some(old_part) = parts.get(0) {
        let nums: Vec<&str> = old_part.split(',').collect();
        let start = nums[0].parse::<usize>().unwrap_or(1);
